/* GridIQ Botswana UI v1.7.0
 * Evidence rules:
 * - no fabricated operational grid values;
 * - no synthetic hourly demand/solar series;
 * - official snapshots, live APIs, historical references and external benchmarks are visibly separated.
 */
'use strict';

const GRID_VERSION='1.7.0';
const STORAGE_KEY='gridiq-botswana-ui-v1.7';
window.__GRID_BOOTED=false;
const FIXTURE_MODE=new URLSearchParams(location.search).has('fixture');

const $=s=>document.querySelector(s);
const $$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmt=(n,d=0)=>Number(n).toLocaleString(undefined,{maximumFractionDigits:d,minimumFractionDigits:d});
const compact=n=>Intl.NumberFormat(undefined,{notation:'compact',maximumFractionDigits:1}).format(Number(n));
const pct=n=>`${fmt(n,1)}%`;

function toast(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>t.hidden=true,4200)}
async function api(path,options={}){const r=await fetch(path,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});if(!r.ok){let d={};try{d=await r.json()}catch{};throw new Error(d.detail||`HTTP ${r.status}`)}return r.json()}

function loadStyleOnce(id,href){if(document.getElementById(id))return;const l=document.createElement('link');l.id=id;l.rel='stylesheet';l.href=href;document.head.appendChild(l)}
function loadScriptOnce(id,src,globalName,timeoutMs=15000){if(globalName&&window[globalName])return Promise.resolve(true);const existing=document.getElementById(id);if(existing?.dataset.loaded==='1')return Promise.resolve(true);return new Promise((resolve,reject)=>{const s=existing||document.createElement('script');if(!existing){s.id=id;s.src=src;s.async=true;s.crossOrigin='anonymous';document.head.appendChild(s)}const timer=setTimeout(()=>reject(new Error(`Timed out loading ${src}`)),timeoutMs);s.onload=()=>{clearTimeout(timer);s.dataset.loaded='1';resolve(true)};s.onerror=()=>{clearTimeout(timer);reject(new Error(`Failed to load ${src}`))}})}
async function ensureVendors(){if(FIXTURE_MODE){setVendorPill(false);return false}const jobs=[];if(!window.L){loadStyleOnce('leaflet-css','https://unpkg.com/leaflet@1.9.4/dist/leaflet.css');jobs.push(loadScriptOnce('leaflet-js','https://unpkg.com/leaflet@1.9.4/dist/leaflet.js','L'))}if(!window.Chart)jobs.push(loadScriptOnce('chart-js','https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js','Chart'));if(!jobs.length){setVendorPill(true);return true}const r=await Promise.allSettled(jobs);const ok=r.every(x=>x.status==='fulfilled');setVendorPill(ok);return ok}
function setVendorPill(ok){const p=$('#vendorPill');if(!p)return;p.textContent=ok?'Visual libs ready':'Visual libs degraded';p.className=`pill ${ok?'ok':'bad'}`}

const charts=new Map();
const colors={cyan:'#42d6e7',green:'#5de39b',amber:'#f4b85c',red:'#ff6f79',blue:'#5fa9ff',violet:'#9b89ff',grid:'rgba(120,150,170,.12)',text:'#8296a8'};
function chartBase(){return{responsive:true,maintainAspectRatio:false,animation:{duration:250},interaction:{mode:'index',intersect:false},plugins:{legend:{labels:{color:colors.text,boxWidth:9,boxHeight:9,font:{size:10}}},tooltip:{backgroundColor:'#0c1722',borderColor:'#2a4052',borderWidth:1,titleColor:'#e8f0f7',bodyColor:'#c4d1dc'}},scales:{x:{ticks:{color:colors.text,font:{size:9},autoSkip:true,maxTicksLimit:12,maxRotation:0},grid:{display:false}},y:{ticks:{color:colors.text,font:{size:9}},grid:{color:colors.grid},beginAtZero:true}}}}
function mountChart(id,config){const el=document.getElementById(id);if(!el||!window.Chart)return false;if(charts.has(id)){try{charts.get(id).destroy()}catch{}charts.delete(id)}charts.set(id,new Chart(el,config));return true}
function lineChart(id,labels,series,opts={}){const o=chartBase();if(opts.beginAtZero===false)o.scales.y.beginAtZero=false;return mountChart(id,{type:'line',data:{labels,datasets:series.map((s,i)=>({label:s.label,data:s.data,borderColor:s.color||[colors.cyan,colors.green,colors.amber,colors.violet][i%4],backgroundColor:(s.color||colors.cyan)+'20',fill:!!s.fill,tension:.28,borderWidth:2,pointRadius:opts.points?2:0,spanGaps:true}))},options:o})}
function barChart(id,labels,series,opts={}){const o=chartBase();if(opts.horizontal){o.indexAxis='y';o.scales.x={ticks:{color:colors.text,font:{size:9}},grid:{color:colors.grid},beginAtZero:true};o.scales.y={ticks:{color:colors.text,font:{size:9}},grid:{display:false}}}return mountChart(id,{type:'bar',data:{labels,datasets:series.map((s,i)=>({label:s.label,data:s.data,backgroundColor:s.color||[colors.cyan,colors.green,colors.amber,colors.violet][i%4],borderRadius:5,borderSkipped:false}))},options:o})}
function doughnutChart(id,labels,data){return mountChart(id,{type:'doughnut',data:{labels,datasets:[{data,backgroundColor:[colors.amber,colors.green,colors.violet,colors.cyan,colors.red],borderColor:'#0c1722',borderWidth:4}]},options:{responsive:true,maintainAspectRatio:false,cutout:'70%',plugins:{legend:{position:'right',labels:{color:colors.text,boxWidth:9,font:{size:10}}},tooltip:{backgroundColor:'#0c1722',borderColor:'#2a4052',borderWidth:1}}}})}

/* Map lifecycle. The map is recreated whenever #energyMap is recreated by page navigation. */
let map=null,layers={},mapContainer=null,selectionCb=()=>{},lastGeoJSON=null;
function resetDetachedMap(){if(!map)return;const current=document.getElementById('energyMap');if(!mapContainer||!mapContainer.isConnected||mapContainer!==current){try{map.remove()}catch{}map=null;layers={};mapContainer=null}}
function showMapFallback(msg){const el=$('#energyMap');if(el)el.innerHTML=`<div class="map-fallback"><b>Map unavailable</b><span>${esc(msg)}</span></div>`}
function ensureMap(){resetDetachedMap();if(!window.L){showMapFallback('Leaflet has not loaded. Internet access is required for the OpenStreetMap basemap library.');return null}if(map)return map;const target=$('#energyMap');if(!target)return null;target.innerHTML='';mapContainer=target;map=L.map(target,{zoomControl:true,preferCanvas:true,minZoom:5,maxZoom:16}).setView([-22.2,24.7],6);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);layers.lines=L.layerGroup().addTo(map);layers.assets=L.layerGroup().addTo(map);layers.topology=L.layerGroup().addTo(map);layers.benchmark=L.layerGroup();map.on('click',e=>selectionCb({type:'location',lat:e.latlng.lat,lng:e.latlng.lng,name:'Selected analysis point'}));setTimeout(()=>map.invalidateSize(),70);return map}
function voltageColor(raw=''){const vals=String(raw||'').replace(/,/g,';').split(';').map(x=>Number(x.trim())).filter(Number.isFinite);const v=vals.length?Math.max(...vals):0;if(v>=350000)return '#ff7c68';if(v>=180000)return '#f4b85c';if(v>=110000)return '#42d6e7';if(v>=50000)return '#5fa9ff';return '#657f94'}
function assetIcon(p){const c=p.power==='substation'?colors.cyan:(p.power==='plant'||p.power==='generator'?colors.green:colors.violet);return L.divIcon({className:'',html:`<div style="width:13px;height:13px;border-radius:50%;background:${c};border:3px solid #071019;box-shadow:0 0 0 1px ${c},0 0 12px ${c}66"></div>`,iconSize:[13,13],iconAnchor:[6,6]})}
function topologyMarkers(fc){const g=new Map();for(const f of fc.features||[]){if(f.geometry?.type!=='LineString')continue;const c=f.geometry.coordinates||[];for(let i=0;i<c.length;i++){const [lon,lat]=c[i];const k=`${lon.toFixed(5)},${lat.toFixed(5)}`;if(!g.has(k))g.set(k,{lon,lat,n:new Set()});if(i>0){const [plon,plat]=c[i-1],pk=`${plon.toFixed(5)},${plat.toFixed(5)}`;g.get(k).n.add(pk)}if(i<c.length-1){const [nlon,nlat]=c[i+1],nk=`${nlon.toFixed(5)},${nlat.toFixed(5)}`;g.get(k).n.add(nk)}}}return Array.from(g.values()).filter(x=>x.n.size===1||x.n.size>=3)}
function renderPowerData(result,{fit=true}={}){const m=ensureMap();if(!m)return;lastGeoJSON=result?.data||result;if(!lastGeoJSON)return;layers.lines.clearLayers();layers.assets.clearLayers();layers.topology.clearLayers();for(const f of lastGeoJSON.features||[]){const p=f.properties||{};let layer;if(f.geometry?.type==='LineString'){layer=L.geoJSON(f,{style:{color:voltageColor(p.voltage),weight:2.4,opacity:.82}});layers.lines.addLayer(layer)}else if(f.geometry?.type==='Point'){const [lon,lat]=f.geometry.coordinates;layer=L.marker([lat,lon],{icon:assetIcon(p)});layers.assets.addLayer(layer)}else{layer=L.geoJSON(f,{style:{color:colors.cyan,weight:1,fillOpacity:.10}});layers.assets.addLayer(layer)}layer.bindTooltip(`${p.name||p.power||'Power asset'}${p.voltage?` · ${p.voltage} V`:''}`,{className:'asset-tip'});layer.on('click',()=>selectionCb({type:'osm',feature_id:f.id,...p,geometry:f.geometry}))}for(const n of topologyMarkers(lastGeoJSON)){const degree=n.n.size;const c=degree>=3?colors.red:colors.blue;L.circleMarker([n.lat,n.lon],{radius:degree>=3?4.5:3,color:c,weight:1.5,fillColor:c,fillOpacity:.9}).bindTooltip(degree>=3?`OSM geometry junction · degree ${degree}`:'OSM geometry endpoint').addTo(layers.topology)}if(fit){try{const group=L.featureGroup([layers.lines,layers.assets]);const b=group.getBounds();if(b.isValid())m.fitBounds(b.pad(.04))}catch{}}}
function setMapLayer(name,visible){const m=ensureMap();if(!m||!layers[name])return;if(visible&&!m.hasLayer(layers[name]))layers[name].addTo(m);if(!visible&&m.hasLayer(layers[name]))m.removeLayer(layers[name])}
function utilColor(v){if(v==null)return '#657f94';if(v>=100)return colors.red;if(v>=80)return colors.amber;if(v>=50)return colors.cyan;return colors.green}
function renderBenchmarkFlows(result){const m=ensureMap();if(!m||!layers.benchmark||!lastGeoJSON)return;layers.benchmark.clearLayers();if(!result?.supported)return;const byId=new Map((result.flows||[]).map(x=>[x.feature_id,x]));for(const f of lastGeoJSON.features||[]){const r=byId.get(f.id);if(!r||f.geometry?.type!=='LineString')continue;L.geoJSON(f,{style:{color:utilColor(r.utilization_pct),weight:5,opacity:.78,dashArray:'8 5'}}).bindTooltip(`Benchmark transfer: ${fmt(r.abs_flow_mw,1)} MW · ${fmt(r.utilization_pct,1)}% of benchmark secure rating`,{className:'asset-tip'}).addTo(layers.benchmark)}layers.benchmark.addTo(m)}


/* GridIQ Botswana UI v1.7.0 — requirements-traceable planning interface. */
const NAV=[
  ['overview','Overview'],['network','Network & E2'],['optimizer','Optimizer E1'],['criticality','Criticality E3'],['villagefit','VillageFit E4'],
  ['generation','Generation'],['storage','Storage'],['demand','Demand'],['data','Data Evidence'],['audit','Audit']
];
const DEFAULTS={page:'overview',selected:{lat:-24.65,lon:25.91,name:'Gaborone analysis point'},topologyVisible:true,benchmarkVisible:true,
 engineering:{voltage_kv:220,case:'reference',transfer_mw:100,source_lat:-22.52,source_lon:27.05,sink_lat:-24.65,sink_lon:25.91,result:null},
 e1:{source_year:2025,import_capacity_limit_mw:190,import_energy_price_usd_per_mwh:100,max_solar_mw:2500,max_wind_mw:0,max_bess_mw:1000,bess_duration_h:4,real_discount_rate:.08,grid_cost_case:'reference',use_selected_site:true,result:null,chronological_result:null},
 e3:{voltage_kv:'',result:null},
 e4:{village_id:'ukhwi',grid_cost_case:'reference',use_live_nasa:true,use_live_gep:true,nasa_days:30,annual_kwh_per_household:'',peak_kw_per_household:'',evening_energy_share_pct:'',collectable_cattle_manure_kg_per_day:'',biogas_yield_case:'reference',custom:null,result:null,dreQuery:'',dreResults:[]},
 lossModelled:'',lossScope:'transmission',lossResult:null,nasa:null,gep:null,worldpop:null,drePoint:null,scenario:{storage_mw:100,storage_mwh:400,result:null}}
let state=structuredClone(DEFAULTS);
const data={};
function restore(){try{const x=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(x)state={...state,...x,selected:{...state.selected,...(x.selected||{})},engineering:{...state.engineering,...(x.engineering||{})},e1:{...state.e1,...(x.e1||{})},e3:{...state.e3,...(x.e3||{})},e4:{...state.e4,...(x.e4||{})},scenario:{...state.scenario,...(x.scenario||{})}}}catch{}}
function persist(){try{const copy=structuredClone(state);copy.e4.dreResults=[];localStorage.setItem(STORAGE_KEY,JSON.stringify(copy))}catch{}}
function setState(path,value){const keys=path.split('.');let o=state;for(let i=0;i<keys.length-1;i++)o=o[keys[i]];o[keys.at(-1)]=value;persist()}
const tag=(t,c='official')=>`<span class="source-tag ${c}">${esc(t)}</span>`;
const panel=(title,body,sub='')=>`<section class="panel"><div class="panel-head"><h2>${esc(title)}</h2><span>${esc(sub)}</span></div><div class="panel-body">${body}</div></section>`;
const metric=(label,value,unit='',note='')=>`<section class="panel metric"><label>${esc(label)}</label><div class="value">${value==null?'—':esc(value)}${unit?`<span class="unit">${esc(unit)}</span>`:''}</div>${note?`<div class="note">${esc(note)}</div>`:''}</section>`;
const callout=(html,type='warn')=>`<div class="callout ${type}">${html}</div>`;
const mapPanel=(title='Botswana energy topology')=>`<section class="panel"><div class="panel-head"><h2>${esc(title)}</h2><span>OSM mapped infrastructure · not BPC operating state</span></div><div class="map-wrap compact"><div id="energyMap" class="map"></div><div class="map-tools"><button class="map-chip" id="loadOsm">${data.osm?'Refresh OSM':'Load OSM topology'}</button><button class="map-chip ${state.topologyVisible?'active':''}" id="toggleTopology">Topology</button><button class="map-chip ${state.benchmarkVisible?'active':''}" id="toggleBenchmark">Benchmark flow</button></div><div class="map-legend"><span><i class="legend-line" style="background:#ff7c68"></i>≥350 kV</span><span><i class="legend-line" style="background:#f4b85c"></i>180–349 kV</span><span><i class="legend-line" style="background:#42d6e7"></i>110–179 kV</span><span>Click map to set analysis point</span></div></div></section>`;
function table(headers,rows){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function numField(id,label,value,step='1',extra=''){return `<label>${esc(label)}<input id="${id}" type="number" step="${step}" value="${esc(value??'')}" ${extra}></label>`}
function selectField(id,label,value,opts){return `<label>${esc(label)}<select id="${id}">${opts.map(([v,n])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`}
function sourceLink(url,label='Source'){return url?`<a class="source-link" target="_blank" rel="noopener" href="${esc(url)}">${esc(label)} ↗</a>`:''}
function fmtUsd(v){return v==null?'—':`$${compact(v)}`}
function statusBadge(s){const c=s.startsWith('blocked')?'unknown':s.startsWith('implemented')?'official':'benchmark';return tag(s.replaceAll('_',' '),c)}

function viewOverview(){const s=data.supply||{},loss=data.losses?.validation_anchor||{},bpc=data.bpcGrid?.network||{},base=data.baseline||{};const low=s.lowest_quarter_local_share||{};return `<div class="workspace">
<div class="evidence-strip">${tag('Official Botswana statistics')}${tag('OSM live','live')}${tag('World Bank GEP/DRE','live')}${tag('Benchmarks explicitly labelled','benchmark')}</div>
<div class="grid network-head">${metric('2018–22 domestic supply',s.five_year_2018_2022?.local_generation_share_pct!=null?fmt(s.five_year_2018_2022.local_generation_share_pct,2):null,'%','Derived from Statistics Botswana quarters')}${metric('Historical low local share',low.local_generation_share_pct!=null?fmt(low.local_generation_share_pct,2):null,'%',low.period||'')}${metric('BPC FY2023 losses',loss.loss_gwh_table!=null?fmt(loss.loss_gwh_table,0):null,'GWh',loss.loss_pct!=null?`${loss.loss_pct}% of units`:'' )}${metric('Q1 2026 Eskom share',base.q1_2026?.eskom_share_of_imports_pct!=null?fmt(base.q1_2026.eskom_share_of_imports_pct,1):null,'%','Published quarterly import mix')}</div>
<div class="grid network-split">${mapPanel()}<div class="right-col">${panel('Current public BPC grid',`<div class="fact-list"><div><span>400 kV</span><b>${fmt(bpc.transmission_km_by_voltage?.['400_kv']||0)} km</b></div><div><span>220 kV</span><b>${fmt(bpc.transmission_km_by_voltage?.['220_kv']||0)} km</b></div><div><span>132 kV</span><b>${fmt(bpc.transmission_km_by_voltage?.['132_kv']||0)} km</b></div><div><span>Substations</span><b>${fmt(bpc.substations_count||0)}</b></div></div>`,`Official public snapshot`)}${panel('Decision boundary',callout(`<b>Planning twin, not SCADA.</b><p>Mapped topology and open-data model outputs can support investment screening. Real congestion, spare transformer capacity and outage probability remain unknown without BPC engineering/operational data.</p>`))}</div></div>
<div class="grid bottom-grid">${panel('Supply history','<div class="chart-box"><canvas id="supplyChart"></canvas></div>')}${panel('BPC loss history','<div class="chart-box"><canvas id="lossChart"></canvas></div>')}${panel('Current capacity',`<div class="fact-list"><div><span>Installed</span><b>${fmt(base.sapp_capacity?.installed_capacity_mw||0)} MW</b></div><div><span>Operating</span><b>${fmt(base.sapp_capacity?.operating_capacity_mw||0)} MW</b></div><div><span>Peak demand</span><b>${fmt(base.sapp_capacity?.peak_demand_mw||0)} MW</b></div><div><span>Peak + reserve</span><b>${fmt(base.sapp_capacity?.peak_plus_reserves_mw||0)} MW</b></div></div>`)}${panel('Rural last mile',`<div class="big-number">${data.rural?.programme_status?.electrified_villages_march_2025||'—'} <small>/ ${data.rural?.programme_status?.gazetted_villages_total_2025||'—'} villages</small></div><p class="muted">Six publicly verified off-grid pilot villages are bundled. The app does not invent the missing current exhaustive unconnected-village register.</p>`)}</div></div>`}

function viewNetwork(){const e=state.engineering,bpc=data.bpcGrid?.network||{},limits=data.sappLimits?.bpc_eskom||[],r=e.result;return `<div class="workspace"><div class="grid network-head">${metric('Official 400 kV',bpc.transmission_km_by_voltage?.['400_kv']||null,'km')}${metric('Official 220 kV',bpc.transmission_km_by_voltage?.['220_kv']||null,'km')}${metric('Official 132 kV',bpc.transmission_km_by_voltage?.['132_kv']||null,'km')}${metric('Official substations',bpc.substations_count||null,'')}</div><div class="grid network-split">${mapPanel('Mapped topology + benchmark engineering overlay')}<div class="right-col">${panel('E2 benchmark DC transfer',`<div class="field-grid">${selectField('e2v','Voltage class',e.voltage_kv,[[132,'132 kV'],[220,'220 kV'],[400,'400 kV']])}${selectField('e2case','Line benchmark',e.case,[['conservative','Conservative'],['reference','Reference'],['high_capacity','High capacity']])}${numField('e2mw','Transfer MW',e.transfer_mw,'10')}${numField('e2slat','Source latitude',e.source_lat,'.0001')}${numField('e2slon','Source longitude',e.source_lon,'.0001')}${numField('e2tlat','Sink latitude',e.sink_lat,'.0001')}${numField('e2tlon','Sink longitude',e.sink_lon,'.0001')}</div><div class="button-row" style="margin-top:10px"><button id="runE2" class="btn primary">Run benchmark DC transfer</button><button id="runE2System" class="btn">Run multi-injection benchmark</button><button id="sourceHere" class="btn">Source = selected</button><button id="sinkHere" class="btn">Sink = selected</button></div>${callout('Observed OSM geometry + documented benchmark R/X/current + explicit user transfer. Results are <b>not measured BPC loading</b>.')}`)}${r?panel('E2 result',r.supported?`<div class="screen-result"><div><span>Max benchmark utilisation</span><b>${fmt(r.summary.max_benchmark_utilization_pct,1)}%</b></div><div><span>Approx I²R loss</span><b>${fmt(r.summary.approx_total_i2r_loss_mw,3)} MW</b></div><div><span>Branches ≥80%</span><b>${r.summary.branches_at_or_above_80_pct}</b></div><div><span>Components at voltage</span><b>${r.network_scope.all_mapped_components_at_voltage}</b></div></div>`:callout(`<b>Transfer unsupported.</b><p>${esc(r.reason||'')}</p>`)) : ''}</div></div>
<div class="grid split dashboard-split">${panel('SAPP BPC–Eskom transfer-limit evidence',table(['Corridor','kV','Applicable MW'],limits.map(x=>`<tr><td>${esc(x.corridor||x.name||'')}</td><td>${esc(x.voltage_kv||'')}</td><td>${fmt(x.applicable_transfer_limit_mw||0)}</td></tr>`)) + `<p class="muted">Corridor values are not summed into one national import capacity without network simultaneity/path evidence.</p>`)}${panel('Loss reconciliation',`<div class="big-number">${fmt(data.losses?.validation_anchor?.loss_gwh_table||0)} <small>GWh · ${fmt(data.losses?.validation_anchor?.loss_pct||0,2)}%</small></div>${state.modelLoss?`<p class="muted">GridIQ transmission model bracket: <b>${fmt(state.modelLoss.reconciliation?.modelled_transmission_only_gwh_range?.[0],1)}-${fmt(state.modelLoss.reconciliation?.modelled_transmission_only_gwh_range?.[1],1)} GWh/y</b> (transmission-only; expected to undercount BPC T&D).</p>`:''}<div class="field-grid" style="margin-top:12px">${numField('lossInput','Modelled annual loss GWh',state.lossModelled,'.1','min="0"')}${selectField('lossScope','Model scope',state.lossScope,[['transmission','Transmission model'],['td_system','Matched T&D/system accounting']])}</div><div class="button-row" style="margin-top:10px"><button id="useModelLoss" class="btn subtle">Use GridIQ model result</button><button id="runLoss" class="btn primary">Compare to BPC anchor</button></div>${state.lossResult?.comparison?`<div class="screen-result"><div><span>Difference</span><b>${fmt(state.lossResult.comparison.difference_gwh,1)} GWh</b></div><div><span>Abs error vs anchor</span><b>${fmt(state.lossResult.comparison.absolute_error_pct_of_bpc_anchor,1)}%</b></div></div><p class="muted">${esc(state.lossResult.comparison.interpretation)}</p>`:''}`)}</div></div>`}

function viewOptimizer(){const x=state.e1,r=x.result;return `<div class="workspace"><div class="grid split"><div>${panel('E1 system-wide screening optimizer',`<div class="field-grid">${numField('e1year','Observed source year',x.source_year,'1')}${numField('e1impCap','Import corridor limit MW',x.import_capacity_limit_mw,'10')}${numField('e1price','Import energy price $/MWh',x.import_energy_price_usd_per_mwh,'5')}${numField('e1solar','Max solar MW',x.max_solar_mw,'50')}${numField('e1wind','Max wind MW',x.max_wind_mw,'50')}${numField('e1bess','Max BESS MW',x.max_bess_mw,'50')}${numField('e1dur','BESS duration h',x.bess_duration_h,'1')}${numField('e1disc','Real discount rate',x.real_discount_rate,'.01')}${selectField('e1grid','Grid cost sensitivity',x.grid_cost_case,[['low','Low'],['reference','Reference'],['high','High']])}</div><label class="control" style="margin-top:10px"><span><input id="e1site" type="checkbox" ${x.use_selected_site?'checked':''}> Add selected map point as spatial candidate</span><small>${esc(state.selected.name)} · ${fmt(state.selected.lat,4)}, ${fmt(state.selected.lon,4)}</small></label><div class="button-row"><button id="runE1" class="btn primary">Run E1 annual LP</button><button id="runE1Chrono" class="btn">Run 24h benchmark chronology</button><button id="saveE1A" class="btn subtle">Save as A</button><button id="saveE1B" class="btn subtle">Save as B</button></div>${callout('<b>Two scopes:</b> annual LP uses observed annual balance. The 24h chronology uses a normalized Eskom hourly demand benchmark plus NASA solar shape scaled to Botswana published anchors; it is not measured BPC dispatch.')}${e1CompareHtml()}`)}</div><div>${panel('Candidate map',`<div class="map-wrap compact"><div id="energyMap" class="map"></div><div class="map-tools"><button class="map-chip" id="loadOsm">${data.osm?'Refresh OSM':'Load OSM topology'}</button></div></div>`)} </div></div>${r?`<div class="section-title"><h2>E1 result</h2><p>${esc(r.model||'')}</p></div><div class="grid network-head">${metric('Solar build',r.solution?.solar_mw,'MW')}${metric('Wind build',r.solution?.wind_mw,'MW')}${metric('BESS',r.solution?.bess_mw,'MW',r.solution?.bess_mwh!=null?`${fmt(r.solution.bess_mwh,1)} MWh`:'')}${metric('Imports avoided',compact(r.solution?.imports_avoided_mwh||0),'MWh/y',`${fmt(r.solution?.imports_avoided_pct_of_baseline||0,1)}% of baseline`)}</div><div class="grid split">${panel('Ranked build plan',table(['Technology','MW','MWh','Candidate / connection'],(r.ranked_build_plan||[]).map(p=>`<tr><td>${esc(p.technology)}</td><td>${fmt(p.build_mw||0,1)}</td><td>${p.build_mwh!=null?fmt(p.build_mwh,1):'—'}</td><td>${esc(p.candidate_site||p.site||'')}<span class="table-sub">${esc(p.connection_point||'')}</span></td></tr>`)))}${panel('Economics & validation',`<div class="fact-list"><div><span>Annualized build cost</span><b>${fmtUsd(r.solution?.annualized_build_cost_usd)}</b></div><div><span>Annual import cost</span><b>${fmtUsd(r.solution?.annual_import_cost_usd)}</b></div><div><span>Total annual screen cost</span><b>${fmtUsd(r.solution?.total_annual_screen_cost_usd)}</b></div>${r.solution?.upfront_build_plus_connection_capex_usd_screen!=null?`<div><span>Upfront + connection CAPEX screen</span><b>${fmtUsd(r.solution.upfront_build_plus_connection_capex_usd_screen)}</b></div>`:''}<div><span>Energy balance residual</span><b>${fmt(r.validation?.energy_balance_residual_mwh||0,4)} MWh</b></div></div><p class="muted">${esc(r.evidence_boundary||'')}</p>`)}</div>`:''}${x.chronological_result?panel('Chronological benchmark result',x.chronological_result.status==='solved'?`<div class="screen-result"><div><span>Solar build</span><b>${fmt(x.chronological_result.solution?.solar_build_mw,1)} MW</b></div><div><span>BESS</span><b>${fmt(x.chronological_result.solution?.bess_power_mw,1)} MW / ${fmt(x.chronological_result.solution?.bess_energy_mwh,1)} MWh</b></div><div><span>Annual imports</span><b>${compact(x.chronological_result.solution?.annual_imports_mwh_representative||0)} MWh</b></div><div><span>Import reduction</span><b>${compact(x.chronological_result.solution?.annual_import_reduction_mwh_vs_same_shape_baseline||0)} MWh</b></div></div><p class="muted">${esc(x.chronological_result.evidence_boundary||'')}</p>`:callout(esc(x.chronological_result.detail||x.chronological_result.solver_message||'Benchmark chronology unavailable'))) : ''}</div>`}

function viewCriticality(){const r=state.e3.result;return `<div class="workspace"><div class="grid split"><div>${mapPanel('E3 mapped topology criticality')}</div><div>${panel('E3 structural screening',`<div class="field-grid">${selectField('e3v','Voltage filter',state.e3.voltage_kv,[['','All mapped'],[132,'132 kV'],[220,'220 kV'],[400,'400 kV']])}</div><div class="button-row" style="margin-top:10px"><button id="runE3" class="btn primary">Run criticality screen</button></div>${callout('<b>Not predictive maintenance.</b> Bridges, articulation points, N-1 geometry partition and edge betweenness describe structural topology only. No failure probability, condition or customer outage count is inferred.')}`)}${panel('BPC data contract',`<p class="muted">To upgrade structural screening into asset-risk prediction: age/commissioning date, ratings, impedance, loading history, condition scores, inspections, failure/repair history, maintenance actions, protection/switch state and asset IDs are required.</p><code>docs/data_contracts/BPC_ENGINEERING_DATA_CONTRACT.md</code>`)}</div></div>${r?`<div class="grid network-head">${metric('Geometry nodes',r.graph.nodes)}${metric('Segments',r.graph.segments)}${metric('Bridges',r.bridge_count)}${metric('Articulation points',r.articulation_point_count)}</div><div class="grid split">${panel('Ranked bridge watch-list',table(['Asset','Impact','Isolated geometry nodes'],(r.watchlist||[]).slice(0,20).map(x=>`<tr><td>${esc((x.mapped_feature_names||[]).join(', ')||'Mapped segment')}</td><td>${fmt(x.structural_impact_pct,1)}%</td><td>${x.islanded_geometry_nodes_if_out}</td></tr>`)))}${panel('Edge betweenness',table(['Asset','Centrality'],(r.edge_betweenness||[]).slice(0,20).map(x=>`<tr><td>${esc((x.mapped_feature_names||[]).join(', ')||'Mapped segment')}</td><td>${fmt(x.edge_betweenness,5)}</td></tr>`)) + `<p class="muted">${esc(r.method)}</p>`)}</div>`:''}</div>`}

function villageOptions(){return (data.rural?.pilot_villages||[]).map(v=>[v.id,`${v.name} · pop ${fmt(v.population_2022)}`])}
function viewVillageFit(){const x=state.e4,r=x.result;const custom=x.custom;return `<div class="workspace"><div class="grid split"><div>${mapPanel('VillageFit spatial evidence')}</div><div>${panel('E4 VillageFit',`<div class="field-grid">${selectField('e4village','Verified pilot village',x.village_id,villageOptions())}${selectField('e4grid','Grid extension cost',x.grid_cost_case,[['low','Low benchmark'],['reference','Reference benchmark'],['high','High benchmark']])}${numField('e4annual','Annual kWh/household (optional)',x.annual_kwh_per_household,'10','min="1"')}${numField('e4peak','Peak kW/household (optional)',x.peak_kw_per_household,'.01','min=".01"')}${numField('e4evening','Evening energy share % (optional)',x.evening_energy_share_pct,'1','min="0" max="100"')}${numField('e4manure','Collectable cattle manure kg/day (optional)',x.collectable_cattle_manure_kg_per_day,'10','min="1"')}${selectField('e4bio','FAO biogas yield case',x.biogas_yield_case,[['low','Low'],['reference','Reference'],['high','High']])}</div><label class="control"><span><input id="e4nasa" type="checkbox" ${x.use_live_nasa?'checked':''}> NASA POWER resource query</span></label><label class="control"><span><input id="e4gep" type="checkbox" ${x.use_live_gep?'checked':''}> World Bank GEP modelled resource query</span></label><div class="button-row"><button id="runE4" class="btn primary">Run VillageFit</button><button id="customSelected" class="btn">Use selected point as custom settlement</button><button id="scoreAllPilots" class="btn subtle">Score all six pilot villages</button></div>${bulkTableHtml()}${custom?callout(`<b>Custom settlement:</b> ${esc(custom.name)} · population ${fmt(custom.population)}. This is explicit input, not a verified unconnected-status claim.`,'good'):''}`)}${panel('DRE Atlas settlement search',`<div class="field-grid"><label>Settlement name<input id="dreQ" value="${esc(x.dreQuery)}" placeholder="e.g. Bere"></label></div><div class="button-row" style="margin-top:8px"><button id="searchDre" class="btn">Search World Bank DRE</button></div>${x.dreResults.length?table(['Settlement','Population','Grid distance field','Action'],x.dreResults.slice(0,10).map((d,i)=>`<tr><td>${esc(d.village_name||'Unnamed')}<span class="table-sub">${esc(d.admin_cgaz_2||d.admin_cgaz_1||'')}</span></td><td>${d.population?fmt(d.population):'—'}</td><td>${d.distance_to_existing_transmission_lines??'—'}</td><td><button class="btn useDre" data-i="${i}">Use</button></td></tr>`)):'<p class="muted">Search the 2025 World Bank Botswana DRE settlement clusters. DRE is not treated as BPC connection-status truth.</p>'}`)}</div></div>${r?`<div class="section-title"><h2>VillageFit result · ${esc(r.village.name)}</h2><p>${esc(r.evidence_boundary)}</p></div><div class="grid network-head">${metric('Population',fmt(r.village.population_2022))}${metric('OSM grid distance',r.grid_proximity?.distance_km!=null?fmt(r.grid_proximity.distance_km,1):null,'km',r.grid_proximity?.status||'')}${metric('Grid CAPEX screen',r.capex_comparison?.grid_extension_capex_usd_screen!=null?fmtUsd(r.capex_comparison.grid_extension_capex_usd_screen):null)}${metric('Solar+BESS CAPEX',r.capex_comparison?.solar_bess_capex_usd_screen!=null?fmtUsd(r.capex_comparison.solar_bess_capex_usd_screen):null,'',r.sizing?.status||'')}</div><div class="grid split">${panel('Technology evidence',table(['Technology','Score/status','Evidence'],(r.resource_fit||[]).map(t=>`<tr><td>${esc(t.technology)}</td><td>${t.score!=null?fmt(t.score):esc(t.status)}</td><td>${esc(t.evidence||'')}</td></tr>`)))}${panel('Right-sizing / feedstock',`<div class="fact-list"><div><span>Estimated households</span><b>${fmt(r.sizing?.estimated_households_from_population||0,1)}</b></div><div><span>Annual demand</span><b>${r.sizing?.annual_demand_mwh!=null?fmt(r.sizing.annual_demand_mwh,1)+' MWh':'UNKNOWN'}</b></div><div><span>PV screen</span><b>${r.sizing?.solar_pv_mw_screen!=null?fmt(r.sizing.solar_pv_mw_screen,3)+' MW':'UNKNOWN'}</b></div><div><span>BESS screen</span><b>${r.sizing?.bess_mwh_screen!=null?fmt(r.sizing.bess_mwh_screen,2)+' MWh':'UNKNOWN'}</b></div><div><span>Historical district cattle</span><b>${r.feedstock_context?.historical_district_cattle_2015?.cattle?fmt(r.feedstock_context.historical_district_cattle_2015.cattle):'No exact district match'}</b></div><div><span>Biogas volume</span><b>${r.feedstock_context?.biogas_screen?.biogas_m3_per_day_screen!=null?fmt(r.feedstock_context.biogas_screen.biogas_m3_per_day_screen,1)+' m³/day':'UNKNOWN'}</b></div></div>`)}</div>`:''}</div>`}

function viewGeneration(){const b=data.baseline||{},q=b.q1_2026||{};return `<div class="workspace"><div class="grid network-head">${metric('Q1 2026 coal share',q.coal_share_pct!=null?fmt(q.coal_share_pct,1):null,'%')}${metric('Q1 2026 solar share',q.solar_share_pct!=null?fmt(q.solar_share_pct,1):null,'%')}${metric('Local generation coverage',q.local_generation_share_of_distribution_pct!=null?fmt(q.local_generation_share_of_distribution_pct,1):null,'%')}${metric('Eskom import share',q.eskom_share_of_imports_pct!=null?fmt(q.eskom_share_of_imports_pct,1):null,'%')}</div><div class="grid split">${panel('Generation / imports history','<div class="chart-box tall"><canvas id="genChart"></canvas></div>')}${panel('Resource query at selected point',`<p><b>${esc(state.selected.name)}</b><br>${fmt(state.selected.lat,4)}, ${fmt(state.selected.lon,4)}</p><div class="button-row"><button id="loadNasa" class="btn primary">Query NASA POWER</button><button id="loadGep" class="btn">Query World Bank GEP</button></div>${state.nasa?`<div class="resource-point"><small>NASA POWER · live</small><b>${state.nasa.rows?.length||0} daily observations</b><p>Mean GHI: ${fmt((state.nasa.rows||[]).filter(x=>x.ghi!=null).reduce((a,x)=>a+x.ghi,0)/Math.max(1,(state.nasa.rows||[]).filter(x=>x.ghi!=null).length),2)} kWh/m²/day</p></div>`:''}${state.gep?.record?`<div class="resource-point"><small>World Bank GEP · modelled open input</small><b>GHI ${esc(state.gep.record.GHI??'—')} · WindCF ${esc(state.gep.record.WindCF??'—')}</b><p>Pop2025 ${esc(state.gep.record.Pop2025??'—')} · Current HV distance ${esc(state.gep.record.CurrentHVLineDist??'—')}</p></div>`:''}`)}</div></div>`}
function viewStorage(){const b=data.storage?.utility_scale_bess_2024||{};const s=state.scenario;return `<div class="workspace"><div class="grid network-head">${metric('NREL RTE',b.round_trip_efficiency_pct_nrel_atb!=null?fmt(b.round_trip_efficiency_pct_nrel_atb):null,'%','Technology benchmark')}${metric('Installed cost',b.global_total_installed_cost_usd_per_kwh!=null?fmt(b.global_total_installed_cost_usd_per_kwh):null,'$/kWh','IRENA/global benchmark')}${metric('Scenario power',fmt(s.storage_mw),'MW')}${metric('Scenario energy',fmt(s.storage_mwh),'MWh',s.storage_mw?`${fmt(s.storage_mwh/s.storage_mw,1)} h duration`:'')}</div><div class="grid split">${panel('Storage screening controls',`<div class="field-grid">${numField('storMW','BESS power MW',s.storage_mw,'10')}${numField('storMWh','BESS energy MWh',s.storage_mwh,'50')}</div><div class="button-row" style="margin-top:10px"><button id="runStorage" class="btn primary">Run evidence-bounded storage screen</button></div>${callout('Without an hourly Botswana load/renewable dispatch series, this screen evaluates duration, benchmark cost and peak-capacity gap only. It does not fabricate charge/discharge curves.')}`)}${panel('Result',s.result?`<div class="fact-list"><div><span>Duration</span><b>${fmt(s.result.summary.storage_duration_hours,1)} h</b></div><div><span>Benchmark CAPEX</span><b>${fmtUsd(s.result.summary.storage_capex_usd)}</b></div><div><span>Current peak capacity gap</span><b>${fmt(s.result.summary.current_peak_capacity_gap_mw,1)} MW</b></div></div>`:'<p class="muted">Run the screen.</p>')}</div></div>`}
function viewDemand(){const n=data.neus||{},c=data.census||{},ctx=data.district||{};return `<div class="workspace"><div class="grid network-head">${metric('2022 population',fmt(c.total_population||0))}${metric('NEUS grid-connected households',fmt(n.national_access?.connected_households||0))}${metric('NEUS national connection',n.national_access?.grid_connection_pct!=null?fmt(n.national_access.grid_connection_pct,1):null,'%')}${metric('Mapped district joins',`${(ctx.records||[]).filter(x=>x.household_grid_connection_pct!=null).length}/${(ctx.records||[]).length}`)}</div><div class="grid split">${panel('District access evidence',table(['District','Population','Household grid connection','Access-gap index'],(ctx.records||[]).map(x=>`<tr><td>${esc(x.census_district)}</td><td>${fmt(x.population||0)}</td><td>${x.household_grid_connection_pct!=null?fmt(x.household_grid_connection_pct,1)+'%':'Unmatched'}</td><td>${x.population_weighted_access_gap_index!=null?fmt(x.population_weighted_access_gap_index,0):'—'}</td></tr>`)) + `<p class="muted">The access-gap index is not a count of unconnected people; NEUS connection rate is household-based.</p>`)}${panel('Spatial population query',`<p><b>${esc(state.selected.name)}</b><br>${fmt(state.selected.lat,4)}, ${fmt(state.selected.lon,4)}</p><div class="button-row"><button id="loadWorldpop" class="btn primary">WorldPop 10 km query</button><button id="dreNearest" class="btn">Nearest DRE settlement</button></div>${state.worldpop?`<div class="big-number">${fmt(state.worldpop.total_population||0)} <small>people · WorldPop modelled</small></div>`:''}${state.drePoint?.record?`<div class="resource-point"><small>DRE nearest settlement</small><b>${esc(state.drePoint.record.village_name||'Unnamed')}</b><p>Population ${esc(state.drePoint.record.population??'—')} · buildings ${esc(state.drePoint.record.num_buildings??'—')}</p></div>`:''}`)}</div></div>`}
function viewData(){const cats=data.catalog?.datasets||[],gaps=data.gapResolution?.gaps||[];return `<div class="workspace">${panel(`Dataset traceability · ${cats.length} sources`,table(['Dataset','Status','Evidence class','Engines / use','Limitation'],cats.map(d=>`<tr><td><b>${esc(d.name)}</b><span class="table-sub">${sourceLink(d.source_url,'Open source')}</span></td><td>${statusBadge(d.status||'')}</td><td>${esc(d.evidence_class||'')}</td><td>${esc(Array.isArray(d.engines)?d.engines.join(', '):(d.ui_use||''))}</td><td>${esc(d.limitations||'')}</td></tr>`)))}${panel(`Unavailable-data resolution · ${gaps.length} gaps`,table(['Missing Botswana field','Benchmark/proxy','Planning use','Status'],gaps.map(g=>`<tr><td><b>${esc(g.missing)}</b></td><td>${esc(g.benchmark)}</td><td>${esc(g.application)}</td><td>${statusBadge(g.status)}</td></tr>`)))}<div class="grid split dashboard-split">${panel('Evidence manifest',`<div class="big-number">${data.manifest?.files?.length||0} <small>bundled files hashed</small></div><p class="muted">Status: ${esc(data.manifest?.status||'')}</p>`)}${panel('Source rule',callout('<b>Observed → derived → modelled/benchmark → UNKNOWN.</b><p>Missing operational fields are now resolved for planning with named benchmarks wherever technically defensible. Benchmark resolution never becomes BPC-observed truth.</p>','good'))}</div></div>`}
function viewAudit(){const a=data.audit||{scores:{},requirements:[],release_gates:{}};const sc=a.scores||{};return `<div class="workspace"><div class="grid network-head">${metric('UI / application',sc.ui_application!=null?fmt(sc.ui_application,1):null,'/10')}${metric('Problem evidence',sc.problem_evidence!=null?fmt(sc.problem_evidence,1):null,'/10')}${metric('Engine implementation',sc.engine_implementation!=null?fmt(sc.engine_implementation,1):null,'/10')}${metric('Public-data planning product',sc.public_data_planning_product!=null?fmt(sc.public_data_planning_product,1):null,'/10')}</div><div class="grid network-head">${metric('Data coverage',sc.data_coverage!=null?fmt(sc.data_coverage,1):null,'/10')}${metric('Benchmark engineering',sc.benchmark_engineering_capability!=null?fmt(sc.benchmark_engineering_capability,1):null,'/10')}${metric('BPC operational validation',sc.bpc_operational_validation!=null?fmt(sc.bpc_operational_validation,1):null,'/10')}${metric('Whole solution',sc.whole_solution!=null?fmt(sc.whole_solution,1):null,'/10')}${metric('Operationally unvalidated',a.counts?.operationally_unvalidated??0,'',`${a.counts?.closed_at_stated_scope||0}/${a.counts?.requirements||0} closed at stated planning scope`)}</div>${panel('Requirements traceability',table(['Area','Requirement','Status','Evidence'],(a.requirements||[]).map(r=>`<tr><td>${esc(r.area)}</td><td>${esc(r.requirement)}</td><td>${statusBadge(r.status)}</td><td>${esc(r.evidence)}</td></tr>`)))}<div class="grid split dashboard-split">${panel('Release gates',Object.entries(a.release_gates||{}).map(([k,v])=>`<div class="gate ${v?'yes':'no'}"><span>${v?'✓':'×'}</span><b>${esc(k.replaceAll('_',' '))}</b><small>${v?'verified':'not verified / blocked'}</small></div>`).join(''))}${panel('Audit position',callout(`<b>No grade inflation.</b><p>${esc(a.position||'')}</p><p>The public planning score is not BPC operating-state accuracy. Missing BPC engineering data still lowers the whole-solution score.</p>`))}</div></div>`}
function currentView(){return {overview:viewOverview,network:viewNetwork,optimizer:viewOptimizer,criticality:viewCriticality,villagefit:viewVillageFit,generation:viewGeneration,storage:viewStorage,demand:viewDemand,data:viewData,audit:viewAudit}[state.page]||viewOverview}
function titleFor(p){return Object.fromEntries(NAV)[p]||'GridIQ'}
function render(){resetDetachedMap();$('#workspace').innerHTML=currentView()();$('#workspace').classList.add('workspace');$('#pageTitle').textContent=titleFor(state.page);const _ds=document.getElementById('demoStep');if(_ds){const _M={overview:1,network:2,optimizer:3,criticality:4,villagefit:5,data:6,audit:6};_ds.textContent='Step '+(_M[state.page]||'')+'/6';}$$('.navbtn').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));bind();mountVisuals()}
function openDrawer(title,body){$('#drawerTitle').textContent=title;$('#drawerBody').innerHTML=body;$('#drawer').classList.add('open');$('#backdrop').hidden=false}
function bindInput(id,path,parser=v=>v){const el=document.getElementById(id);if(!el)return;el.addEventListener('change',()=>{setState(path,parser(el.type==='checkbox'?el.checked:el.value))})}
function bind(){
 selectionCb=x=>{if(x.type==='location'){state.selected={lat:x.lat,lon:x.lng,name:'Selected analysis point'};persist();toast(`Selected ${fmt(x.lat,4)}, ${fmt(x.lng,4)}`)}else openDrawer(x.name||x.power||'Mapped asset',`<pre>${esc(JSON.stringify(x,null,2))}</pre>`)};
 const lo=$('#loadOsm');if(lo)lo.onclick=()=>loadOsm(true);const tt=$('#toggleTopology');if(tt)tt.onclick=()=>{state.topologyVisible=!state.topologyVisible;persist();setMapLayer('topology',state.topologyVisible);tt.classList.toggle('active',state.topologyVisible)};const tb=$('#toggleBenchmark');if(tb)tb.onclick=()=>{state.benchmarkVisible=!state.benchmarkVisible;persist();setMapLayer('benchmark',state.benchmarkVisible);tb.classList.toggle('active',state.benchmarkVisible)};
 ['e2v','e2case','e2mw','e2slat','e2slon','e2tlat','e2tlon'].forEach((id,i)=>bindInput(id,['engineering.voltage_kv','engineering.case','engineering.transfer_mw','engineering.source_lat','engineering.source_lon','engineering.sink_lat','engineering.sink_lon'][i],v=>i===1?v:Number(v)));if($('#runE2'))$('#runE2').onclick=runE2;if($('#runE2System'))$('#runE2System').onclick=runE2System;if($('#sourceHere'))$('#sourceHere').onclick=()=>{state.engineering.source_lat=state.selected.lat;state.engineering.source_lon=state.selected.lon;persist();render()};if($('#sinkHere'))$('#sinkHere').onclick=()=>{state.engineering.sink_lat=state.selected.lat;state.engineering.sink_lon=state.selected.lon;persist();render()};bindInput('lossInput','lossModelled',v=>v===''?'':Number(v));bindInput('lossScope','lossScope');if($('#runLoss'))$('#runLoss').onclick=runLoss;if($('#useModelLoss'))$('#useModelLoss').onclick=useModelLoss;
 const e1ids=['e1year','e1impCap','e1price','e1solar','e1wind','e1bess','e1dur','e1disc','e1grid','e1site'];const e1paths=['e1.source_year','e1.import_capacity_limit_mw','e1.import_energy_price_usd_per_mwh','e1.max_solar_mw','e1.max_wind_mw','e1.max_bess_mw','e1.bess_duration_h','e1.real_discount_rate','e1.grid_cost_case','e1.use_selected_site'];e1ids.forEach((id,i)=>bindInput(id,e1paths[i],v=>i===8?v:i===9?!!v:Number(v)));if($('#runE1'))$('#runE1').onclick=runE1;if($('#runE1Chrono'))$('#runE1Chrono').onclick=runE1Chrono;if($('#saveE1A'))$('#saveE1A').onclick=()=>saveE1('A');if($('#saveE1B'))$('#saveE1B').onclick=()=>saveE1('B');
 bindInput('e3v','e3.voltage_kv');if($('#runE3'))$('#runE3').onclick=runE3;
 bindInput('e4village','e4.village_id');bindInput('e4grid','e4.grid_cost_case');bindInput('e4annual','e4.annual_kwh_per_household');bindInput('e4peak','e4.peak_kw_per_household');bindInput('e4evening','e4.evening_energy_share_pct');bindInput('e4manure','e4.collectable_cattle_manure_kg_per_day');bindInput('e4bio','e4.biogas_yield_case');bindInput('e4nasa','e4.use_live_nasa',Boolean);bindInput('e4gep','e4.use_live_gep',Boolean);if($('#runE4'))$('#runE4').onclick=runE4;if($('#scoreAllPilots'))$('#scoreAllPilots').onclick=scoreAllPilots;if($('#customSelected'))$('#customSelected').onclick=()=>{const pop=prompt('Population for selected settlement (explicit input):','');if(!pop||!Number(pop))return;state.e4.custom={name:state.selected.name,lat:state.selected.lat,lon:state.selected.lon,population:Number(pop)};persist();render()};if($('#dreQ'))$('#dreQ').oninput=e=>setState('e4.dreQuery',e.target.value);if($('#searchDre'))$('#searchDre').onclick=searchDre;$$('.useDre').forEach(b=>b.onclick=()=>{const d=state.e4.dreResults[Number(b.dataset.i)];state.e4.custom={name:d.village_name||'DRE settlement',lat:Number(d.lat),lon:Number(d.lon),population:Number(d.population)||1};state.selected={name:state.e4.custom.name,lat:state.e4.custom.lat,lon:state.e4.custom.lon};persist();render()});
 if($('#loadNasa'))$('#loadNasa').onclick=loadNasa;if($('#loadGep'))$('#loadGep').onclick=loadGep;if($('#loadWorldpop'))$('#loadWorldpop').onclick=loadWorldpop;if($('#dreNearest'))$('#dreNearest').onclick=loadDrePoint;bindInput('storMW','scenario.storage_mw',Number);bindInput('storMWh','scenario.storage_mwh',Number);if($('#runStorage'))$('#runStorage').onclick=runStorage;
}
async function loadOsm(refresh=false){try{toast('Loading mapped Botswana power infrastructure…');data.osm=await api(`/api/osm/power${refresh?'?refresh=true':''}`);persist();render();toast('OSM topology loaded')}catch(e){toast(e.message)}}
async function runE2(){try{if(!data.osm)await loadOsm(false);state.engineering.result=await api('/api/engineering/transfer',{method:'POST',body:JSON.stringify({...state.engineering,result:undefined})});persist();render();toast('E2 benchmark transfer solved')}catch(e){toast(e.message)}}
async function runLoss(){try{state.lossResult=await api('/api/e2/loss-reconciliation',{method:'POST',body:JSON.stringify({modelled_loss_gwh:state.lossModelled===''?null:Number(state.lossModelled),model_scope:state.lossScope})});persist();render()}catch(e){toast(e.message)}}

async function runE2System(){try{if(!data.osm)await loadOsm(false);const e=state.engineering;state.engineering.result=await api('/api/e2/system-benchmark',{method:'POST',body:JSON.stringify({voltage_kv:Number(e.voltage_kv),case:e.case,injections:[{name:'Benchmark source',lat:Number(e.source_lat),lon:Number(e.source_lon),mw:Number(e.transfer_mw)},{name:'Benchmark sink',lat:Number(e.sink_lat),lon:Number(e.sink_lon),mw:-Number(e.transfer_mw)}]})});persist();render();toast('E2 multi-injection benchmark solved')}catch(e){toast(e.message)}}
async function runE1(){try{const p={...state.e1};delete p.result;delete p.grid_cost_case;delete p.use_selected_site;let path='/api/e1/optimize';if(state.e1.use_selected_site){if(!data.osm)await loadOsm(false);path='/api/e1/site-screen';Object.assign(p,{site_name:state.selected.name,lat:state.selected.lat,lon:state.selected.lon,grid_cost_case:state.e1.grid_cost_case,resource_evidence:state.gep?.record?{source:'World Bank GEP',GHI:state.gep.record.GHI,WindCF:state.gep.record.WindCF}:{status:'not supplied'}})}state.e1.result=await api(path,{method:'POST',body:JSON.stringify(p)});persist();render();toast('E1 optimization complete')}catch(e){toast(e.message)}}

async function runE1Chrono(){try{const x=state.e1;const p={lat:state.selected.lat,lon:state.selected.lon,source_year:Number(x.source_year),peak_demand_mw:Number(data.baseline?.sapp_capacity?.peak_demand_mw||610),import_capacity_limit_mw:Number(x.import_capacity_limit_mw),import_energy_price_usd_per_mwh:Number(x.import_energy_price_usd_per_mwh),max_solar_mw:Number(x.max_solar_mw),max_bess_mw:Number(x.max_bess_mw),bess_duration_h:Number(x.bess_duration_h),real_discount_rate:Number(x.real_discount_rate),nasa_days:14};state.e1.chronological_result=await api('/api/e1/representative-day',{method:'POST',body:JSON.stringify(p)});persist();render();toast('E1 benchmark chronology complete')}catch(e){toast(e.message)}}
async function runE3(){try{if(!data.osm)await loadOsm(false);const q=state.e3.voltage_kv?`?voltage_kv=${state.e3.voltage_kv}&limit=50`:'?limit=50';state.e3.result=await api('/api/e3/criticality'+q);persist();render();toast('E3 criticality complete')}catch(e){toast(e.message)}}
function nullNum(v){return v===''||v==null?null:Number(v)}
async function runE4(){try{if(!data.osm)await loadOsm(false);const x=state.e4,p={village_id:x.village_id,grid_cost_case:x.grid_cost_case,use_live_nasa:x.use_live_nasa,use_live_gep:x.use_live_gep,nasa_days:x.nasa_days,annual_kwh_per_household:nullNum(x.annual_kwh_per_household),peak_kw_per_household:nullNum(x.peak_kw_per_household),evening_energy_share_pct:nullNum(x.evening_energy_share_pct),collectable_cattle_manure_kg_per_day:nullNum(x.collectable_cattle_manure_kg_per_day),biogas_yield_case:x.biogas_yield_case};if(x.custom)Object.assign(p,{custom_name:x.custom.name,custom_lat:x.custom.lat,custom_lon:x.custom.lon,custom_population:x.custom.population});state.e4.result=await api('/api/e4/villagefit',{method:'POST',body:JSON.stringify(p)});persist();render();toast('VillageFit complete')}catch(e){toast(e.message)}}
async function searchDre(){try{const r=await api(`/api/dre/settlements?query=${encodeURIComponent(state.e4.dreQuery)}&limit=20`);state.e4.dreResults=r.records||[];persist();render()}catch(e){toast(e.message)}}
async function loadNasa(){try{state.nasa=await api(`/api/nasa/power?lat=${state.selected.lat}&lon=${state.selected.lon}&days=30`);persist();render()}catch(e){toast(e.message)}}
async function loadGep(){try{state.gep=await api(`/api/gep/point?lat=${state.selected.lat}&lon=${state.selected.lon}`);persist();render()}catch(e){toast(e.message)}}
async function loadWorldpop(){try{state.worldpop=await api(`/api/worldpop/population?lat=${state.selected.lat}&lon=${state.selected.lon}&radius_km=10&year=2025`);persist();render()}catch(e){toast(e.message)}}
async function loadDrePoint(){try{state.drePoint=await api(`/api/dre/point?lat=${state.selected.lat}&lon=${state.selected.lon}`);persist();render()}catch(e){toast(e.message)}}
async function runStorage(){try{state.scenario.result=await api('/api/scenario',{method:'POST',body:JSON.stringify({storage_mw:Number(state.scenario.storage_mw),storage_mwh:Number(state.scenario.storage_mwh)})});persist();render()}catch(e){toast(e.message)}}
function mountVisuals(){ensureVendors().then(()=>{if(document.getElementById('energyMap')){ensureMap();if(data.osm)renderPowerData(data.osm,{fit:true});setMapLayer('topology',state.topologyVisible);if(state.engineering.result&&state.benchmarkVisible)renderBenchmarkFlows(state.engineering.result)}if(window.Chart){const q=data.supply?.quarterly||[];if($('#supplyChart'))lineChart('supplyChart',q.map(x=>x.period),[{label:'Local generation share %',data:q.map(x=>x.local_generation_share_pct),color:colors.cyan}],{beginAtZero:false});const lh=data.losses?.annual||[];if($('#lossChart'))lineChart('lossChart',lh.map(x=>x.year),[{label:'BPC loss GWh',data:lh.map(x=>x.loss_gwh),color:colors.amber}],{beginAtZero:false});if($('#genChart'))lineChart('genChart',q.map(x=>x.period),[{label:'Generation MWh',data:q.map(x=>x.generation_mwh),color:colors.green},{label:'Imports MWh',data:q.map(x=>x.imports_mwh),color:colors.amber}])}})}

async function useModelLoss(){try{const m=await api('/api/engines/loss-reconciliation');state.modelLoss=m;const ref=m.results_by_case?.reference||{};if(ref.annualised_gwh_low!=null&&ref.annualised_gwh_high!=null){state.lossModelled=Math.round((ref.annualised_gwh_low+ref.annualised_gwh_high)/2);}await runLoss();toast('GridIQ model loss fed into the BPC comparison')}catch(e){toast(e.message)}}
function saveE1(slot){if(!state.e1.result){toast('Run E1 first');return}state['e1'+slot]=structuredClone(state.e1.result);persist();render();toast('Saved scenario '+slot)}
function e1CompareHtml(){const a=state.e1A,b=state.e1B;if(!a||!b)return '';const ca=a.solution?.total_annual_screen_cost_usd||0,cb=b.solution?.total_annual_screen_cost_usd||0;
return `<div class="section-title" style="margin-top:12px"><h3>A/B system-cost comparison</h3><p>Both options are explicit scenario runs; lower total annual screen cost wins.</p></div><div class="screen-result"><div><span>A total annual cost</span><b>${fmtUsd(ca)}</b></div><div><span>B total annual cost</span><b>${fmtUsd(cb)}</b></div><div><span>Difference (A - B)</span><b>${fmtUsd(ca-cb)}</b></div><div><span>Imports avoided A / B</span><b>${fmt(a.solution?.imports_avoided_mwh||0)} / ${fmt(b.solution?.imports_avoided_mwh||0)} MWh</b></div><div><span>Solar MW A / B</span><b>${fmt(a.solution?.solar_mw||0,1)} / ${fmt(b.solution?.solar_mw||0,1)}</b></div><div><span>BESS MWh A / B</span><b>${fmt(a.solution?.bess_mwh||0,1)} / ${fmt(b.solution?.bess_mwh||0,1)}</b></div></div>`}
function bulkTableHtml(){if(!state.e4.bulk)return '';return panel('Six-pilot comparison',table(['Village','District','Grid km','PV MW','BESS MWh'],state.e4.bulk.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.district||'')}</td><td>${r.grid_km!=null?fmt(r.grid_km,1):'&mdash;'}</td><td>${r.pv!=null?fmt(r.pv,3):'&mdash;'}</td><td>${r.bess!=null?fmt(r.bess,2):'&mdash;'}</td></tr>`)))}
async function scoreAllPilots(){try{if(!data.osm)await loadOsm(false);const x=state.e4;const ids=(data.rural?.pilot_villages||[]).map(v=>v.id);state.e4.bulk=[];for(const id of ids){const p={village_id:id,grid_cost_case:x.grid_cost_case,annual_kwh_per_household:nullNum(x.annual_kwh_per_household),peak_kw_per_household:nullNum(x.peak_kw_per_household),evening_energy_share_pct:nullNum(x.evening_energy_share_pct),use_live_nasa:x.use_live_nasa,use_live_gep:x.use_live_gep};const r=await api('/api/e4/villagefit',{method:'POST',body:JSON.stringify(p)});state.e4.bulk.push({name:r.village?.name,district:r.village?.district_context,grid_km:r.grid_proximity?.distance_km,pv:r.sizing?.solar_pv_mw_screen,bess:r.sizing?.bess_mwh_screen});}persist();render();toast('Scored '+ids.length+' verified pilot villages')}catch(e){toast(e.message)}}

async function boot(){restore();window.__GRID_BOOTED=true;clearTimeout(window.__GRID_BOOT_TIMER);$('#updatedAt').textContent='Evidence snapshot · 13 Sep 2026';const _demo=new URLSearchParams(location.search).get('demo')==='1';const _demoPages=['overview','network','optimizer','criticality','villagefit','data','audit'];const _nav=(_demo?NAV.filter(([p])=>_demoPages.includes(p)):NAV);$('#nav').innerHTML=_nav.map(([p,n])=>`<button class="navbtn" data-page="${p}">${n}</button>`).join('');if(_demo){const _strip=document.createElement('div');_strip.className='evidence-banner';_strip.id='demoStrip';_strip.innerHTML='<b>DEMO</b> &middot; <span id="demoStep"></span> <button class="btn subtle" id="resetDemo" style="float:right">Reset demo</button>';document.querySelector('.subbar').insertAdjacentElement('afterend',_strip);$('#resetDemo').onclick=()=>{localStorage.removeItem(STORAGE_KEY);location.reload()};}$$('.navbtn').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;persist();render()});$$('[data-go]').forEach(b=>b.onclick=()=>{state.page=b.dataset.go;persist();render()});$('#dataBtn').onclick=()=>{state.page='data';persist();render()};$('#drawerClose').onclick=()=>{$('#drawer').classList.remove('open');$('#backdrop').hidden=true};$('#backdrop').onclick=$('#drawerClose').onclick;
 try{const names=['catalog','baseline','storage','neus','census','district','supply','losses','rural','agri','bpcGrid','gepRef','ren','community','sappLimits','manifest','gapResolution','audit'];const paths=['/api/catalog','/api/baseline','/api/storage-benchmarks','/api/neus','/api/census/districts','/api/demand/district-context','/api/supply/metrics','/api/losses/bpc','/api/rural','/api/agriculture','/api/bpc/grid-public','/api/gep/reference','/api/renewable-benchmarks','/api/community-benchmarks','/api/sapp/transfer-limits','/api/evidence/manifest','/api/benchmarks/gap-resolution','/api/audit'];const vals=await Promise.all(paths.map(p=>api(p)));names.forEach((n,i)=>data[n]=vals[i]);$('#healthPill').textContent='API ready';$('#healthPill').className='pill ok'}catch(e){$('#healthPill').textContent='API degraded';$('#healthPill').className='pill bad';toast(e.message)}render()}
boot().catch(e=>{$('#workspace').innerHTML=`<section class="panel"><div class="panel-head"><h2>Frontend startup failed</h2></div><div class="panel-body">${callout(`<b>${esc(e.message)}</b><p>Open Developer Tools → Console for details.</p>`)}</div></section>`;console.error(e)});
